#include <iostream>

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

class FastSlowPointerTemplate {
public:
    // Core structural loop for cycle detection and entry-point tracking
    ListNode* findCycleStart(ListNode* head) {
        if (head == nullptr || head->next == nullptr) {
            return nullptr;
        }

        ListNode* slow = head;
        ListNode* fast = head;
        bool hasCycle = false;

        // Phase 1: Determine if a cycle exists by looking for an intersection point
        while (fast != nullptr && fast->next != nullptr) {
            slow = slow->next;
            fast = fast->next->next;

            if (slow == fast) {
                hasCycle = true;
                break; // Intersection localized
            }
        }

        if (!hasCycle) {
            return nullptr; // Linear list structure with no cycle present
        }

        // Phase 2: Find the entry point of the cycle
        ListNode* pointer1 = head;
        ListNode* pointer2 = slow; // Keep at intersection point

        while (pointer1 != pointer2) {
            pointer1 = pointer1->next;
            pointer2 = pointer2->next;
        }

        return pointer1; // Meeting point is mathematically the start of the cycle
    }
};

